{
  "claims": [
    {
      "claim": "Alprazolam, a close triazolobenzodiazepine analogue, has high absolute oral bioavailability in humans (0.84-0.91) after sustained-release doses, strongly supporting F >= 20%.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 1"],
      "record_ids": ["Record 1-1", "Record 1-2", "Record 1-3", "Record 1-4"]
    },
    {
      "claim": "Estazolam, a structurally similar benzodiazepine, has 87% oral bioavailability in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 2"],
      "record_ids": ["Record 2-1"]
    },
    {
      "claim": "Adinazolam, a close analogue, has absolute oral bioavailability of about 39-40% in humans, above the 20% threshold.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 4", "Molecule 13"],
      "record_ids": ["Record 4-1", "Record 4-2", "Record 4-3", "Record 4-4", "Record 13-1", "Record 13-2"]
    },
    {
      "claim": "Clobazam, a benzodiazepine, has oral bioavailability of 87-100% in humans, supporting high oral absorption and F >= 20%.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 5"],
      "record_ids": ["Record 5-1", "Record 5-2", "Record 5-3", "Record 5-4", "Record 5-5", "Record 5-6", "Record 5-7", "Record 5-8", "Record 5-9", "Record 5-10"]
    },
    {
      "claim": "Triazolam, a close triazolobenzodiazepine, has reported oral bioavailability mostly between 44% and 85%, with all values above 20%.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 6"],
      "record_ids": ["Record 6-1", "Record 6-2", "Record 6-3", "Record 6-4", "Record 6-5", "Record 6-6", "Record 6-7", "Record 6-8", "Record 6-9", "Record 6-10"]
    },
    {
      "claim": "Alprazolam also has an estimated oral bioavailability of 0.35 in one human data source, still above the 20% threshold.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 14"],
      "record_ids": ["Record 14-1"]
    },
    {
      "claim": "Tenidap and loxapine, although less structurally similar, have oral bioavailability values of 85% and 29%, respectively, both above 20%.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 8", "Molecule 10"],
      "record_ids": ["Record 8-1", "Record 10-1"]
    },
    {
      "claim": "Estazolam in mice had 98% oral bioavailability calculated from AUC after oral and IV doses, supporting high F, though the data are from an animal model.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 18"],
      "record_ids": ["Record 18-1"]
    },
    {
      "claim": "High intestinal absorption and permeability are reported for alprazolam, adinazolam, and flunitrazepam, supporting good oral absorption for the diazepam-like scaffold.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 19", "Molecule 20", "Molecule 21"],
      "record_ids": ["Record 19-1", "Record 20-1", "Record 20-2", "Record 21-1"]
    },
    {
      "claim": "Clinical gut-wall estimates for alprazolam are high (F_G 0.94-0.99) and hepatic intrinsic clearance is low, supporting limited first-pass loss and F >= 20%.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 22", "Molecule 26"],
      "record_ids": ["Record 22-3", "Record 22-9", "Record 22-10", "Record 22-11", "Record 26-1", "Record 26-2"]
    },
    {
      "claim": "Halazepam, a close N-substituted diazepam analogue, had only about 10% absolute oral bioavailability in dogs, which would argue for fail if directly transferred, but this is a dog study and not human.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 11"],
      "record_ids": ["Record 11-1", "Record 11-2"]
    },
    {
      "claim": "Camazepam, a diazepam analogue, had 10-15% systemic availability in rats and mice due to first-pass metabolism, but rodent first-pass effects are not directly predictive of human diazepam bioavailability.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 12"],
      "record_ids": ["Record 12-1", "Record 12-2", "Record 12-3", "Record 12-4"]
    },
    {
      "claim": "Lormetazepam had low oral bioavailability in rhesus monkeys, but the source explicitly notes it is lower than in humans, limiting transferability.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 15"],
      "record_ids": ["Record 15-1"]
    },
    {
      "claim": "One rat study reported alprazolam absolute bioavailability of 0.085, but this contrasts with multiple human studies showing high alprazolam bioavailability and is not decisive for the human diazepam query.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 14"],
      "record_ids": ["Record 14-5"]
    },
    {
      "claim": "Prazepam undergoes almost complete first-pass metabolism in humans, but it is a prodrug-like N-substituted analogue and does not directly measure diazepam oral bioavailability.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 28"],
      "record_ids": ["Record 28-1"]
    },
    {
      "claim": "Low oral bioavailability records for prochlorperazine, loperamide, and zotepine come from structurally unrelated chemotypes with negligible transfer likelihood, so they receive little weight for this diazepam query.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 3", "Molecule 7", "Molecule 9"],
      "record_ids": ["Record 3-1", "Record 3-2", "Record 3-3", "Record 3-4", "Record 3-5", "Record 3-6", "Record 3-7", "Record 3-8", "Record 3-9", "Record 3-10", "Record 7-1", "Record 7-2", "Record 7-3", "Record 7-4", "Record 7-5", "Record 7-6", "Record 7-7", "Record 9-1"]
    },
    {
      "claim": "Oral AUC records for alprazolam and midazolam, and metabolite clearance data for 4'-hydroxydiazepam, do not directly set the F threshold and are therefore of limited utility.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 16", "Molecule 17", "Molecule 27"],
      "record_ids": ["Record 16-1", "Record 16-2", "Record 16-3", "Record 17-1", "Record 27-1", "Record 27-2", "Record 27-3", "Record 27-4", "Record 27-5", "Record 27-6"]
    }
  ],
  "final_prediction": "pass"
}
